class Solution {
  private static final long CAP = 2_000_000L;

  private static long binom(int n, int r) {
    if (r < 0 || r > n) return 0;
    r = Math.min(r, n - r);
    long res = 1;
    for (int t = 1; t <= r; t++) {
      res = res * (n - r + t) / t;
      if (res > CAP) return CAP;
    }
    return res;
  }

  private static long arrangements(int total, int[] cnt) {
    long res = 1;
    int rem = total;
    for (int c : cnt) {
      if (c == 0) continue;
      res = Math.min(CAP, res * binom(rem, c));
      rem -= c;
    }
    return res;
  }

  public String smallestPalindrome(String s, int k) {
    int n = s.length();
    int[] cnt = new int[26];
    for (int i = 0; i < n; i++) cnt[s.charAt(i) - 'a']++;
    char mid = 0;
    for (int c = 0; c < 26; c++) {
      if (cnt[c] % 2 == 1) mid = (char) ('a' + c);
      cnt[c] /= 2;
    }
    int h = n / 2;
    StringBuilder half = new StringBuilder();
    long rest = k;
    for (int p = 0; p < h; p++) {
      boolean placed = false;
      for (int c = 0; c < 26 && !placed; c++) {
        if (cnt[c] == 0) continue;
        cnt[c]--;
        long ways = arrangements(h - p - 1, cnt);
        if (rest <= ways) {
          half.append((char) ('a' + c));
          placed = true;
        } else {
          rest -= ways;
          cnt[c]++;
        }
      }
      if (!placed) return "";
    }
    StringBuilder out = new StringBuilder(half);
    if (mid != 0) out.append(mid);
    out.append(new StringBuilder(half).reverse());
    return out.toString();
  }
}
